from pathlib import Path
p=Path('simulation.html')
s=p.read_text(encoding='utf-8')
css=r'''
/* Recommendation card + stronger CTAs */
.orfab-recommendation-card{margin:24px 0 22px;padding:26px 28px;border:2px solid var(--gold);border-radius:20px;background:linear-gradient(180deg,#fffdf8,#f4efe4);color:var(--blue);box-shadow:0 12px 28px rgba(16,36,58,.10);display:grid;grid-template-columns:minmax(0,1.5fr) minmax(260px,.7fr);gap:28px;align-items:center}.orfab-reco-kicker{font-size:11px;letter-spacing:2.2px;text-transform:uppercase;font-weight:900;color:#607487;margin-bottom:8px}.orfab-reco-title{font-family:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;font-size:clamp(28px,3vw,40px);line-height:1.08;margin:0 0 8px;color:var(--blue)}.orfab-reco-title strong{color:#b47d16;font-weight:700}.orfab-reco-price{font-family:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;font-size:clamp(30px,3.3vw,44px);line-height:1;color:#b47d16;font-weight:700;margin:8px 0 14px}.orfab-reco-note{margin:0;color:#50677a;line-height:1.6;font-size:14px;max-width:820px}.orfab-reco-benefits{border-left:1px solid rgba(16,36,58,.18);padding-left:24px;display:grid;gap:14px}.orfab-reco-benefit{display:flex;gap:10px;align-items:flex-start;font-size:14px;line-height:1.4;color:#29445c;font-weight:700}.orfab-reco-check{flex:0 0 24px;width:24px;height:24px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(180deg,#f3ce77,var(--gold));color:var(--blue);font-size:14px;font-weight:950}.offers-fit-cta-wrap{margin-top:18px!important}.offers-fit-cta{min-height:58px!important;padding:0 30px!important;border-radius:18px!important;background:linear-gradient(180deg,#f3ce77,#d59c35)!important;color:var(--blue)!important;font-size:16px!important;font-weight:900!important;border:2px solid rgba(16,36,58,.08)!important;box-shadow:0 10px 24px rgba(16,36,58,.16)!important}.offers-fit-cta:hover{transform:translateY(-1px);box-shadow:0 14px 28px rgba(16,36,58,.22)!important}.result-actions{display:flex!important;flex-wrap:wrap!important;gap:16px!important;align-items:center!important;justify-content:flex-start!important;margin-top:26px!important;padding:24px 0 8px!important}.result-actions a,.result-actions button{min-height:54px!important;padding:0 24px!important;border-radius:18px!important;font-weight:850!important;font-size:15px!important;opacity:1!important;visibility:visible!important;text-decoration:none!important;box-shadow:0 7px 18px rgba(16,36,58,.14)!important}.result-actions a:not(.primary),.result-actions button:not(.primary){background:var(--cream)!important;color:var(--blue)!important;border:2px solid var(--blue)!important}.result-actions .primary,.result-actions a[style*="gold"],.result-actions button[style*="gold"]{background:linear-gradient(180deg,#f3ce77,#d59c35)!important;color:var(--blue)!important;border:2px solid #c18a23!important}.result-actions a:last-child,.result-actions button:last-child{background:var(--blue)!important;color:var(--cream)!important;border:2px solid var(--blue)!important}.result-actions a:hover,.result-actions button:hover{transform:translateY(-1px)}@media(max-width:800px){.orfab-recommendation-card{grid-template-columns:1fr;padding:22px}.orfab-reco-benefits{border-left:0;border-top:1px solid rgba(16,36,58,.18);padding:18px 0 0}.result-actions{display:grid!important;grid-template-columns:1fr!important}.result-actions a,.result-actions button{width:100%!important;justify-content:center!important}}
'''
if '/* Recommendation card + stronger CTAs */' not in s:
    s=s.replace('</style>',css+'\n</style>',1)
js=r'''
<script id="orfab-recommendation-card-script">
(function(){
 const norm=t=>(t||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
 function floorFor(x){const t=norm((x.text||'')+' '+(x.why||''));if(/plusieurs workflow|differents rythmes|reactiv|fidelis|segment|plusieurs conditions|type de client|orchestr|automatisation avancee|parcours complexes/.test(t))return 2;if(/plusieurs parcours|\d+ parcours|ressaisi|etapes reellement differentes|coordonner les actions|plusieurs canaux|synchronis|adapter les relances|automatiser plusieurs etapes|double saisie|personnalis.*document|document.*automati/.test(t))return 1;return 0}
 function addCard(r){const section=document.getElementById('offersFitSection'),table=document.getElementById('offersFitTable');if(!section||!table)return;const l=r.optimizationLevels||{},items=[...(l.critical||[]),...(l.structuring||[]),...(l.advanced||[])];if(!items.length)return;const max=Math.max(...items.map(floorFor));const offer=max===0?'ESSENTIEL':max===1?'ESSENTIEL+':'SIGNATURE';const price=max===0?'autour de 2 500 €':max===1?'autour de 4 000 €':'autour de 9 000 €';let card=section.querySelector('.orfab-recommendation-card');if(!card){card=document.createElement('div');card.className='orfab-recommendation-card';const cta=section.querySelector('.offers-fit-cta-wrap');if(cta)cta.before(card);else table.after(card)}card.innerHTML=`<div><div class="orfab-reco-kicker">Notre recommandation</div><h3 class="orfab-reco-title">Votre projet se situe probablement dans l’offre <strong>${offer}</strong></h3><div class="orfab-reco-price">${price}</div><p class="orfab-reco-note">Ce montant est une estimation basée sur les besoins que vous venez d’indiquer. Le prix exact sera précisé lors de l’échange, en fonction de la manière dont ces besoins s’articulent dans votre fonctionnement.</p></div><div class="orfab-reco-benefits"><div class="orfab-reco-benefit"><span class="orfab-reco-check">✓</span><span>Un CRM entièrement adapté à votre activité</span></div><div class="orfab-reco-benefit"><span class="orfab-reco-check">✓</span><span>Les optimisations recommandées intégrées au projet</span></div><div class="orfab-reco-benefit"><span class="orfab-reco-check">✓</span><span>Un accompagnement de la conception à la mise en main</span></div></div>`}
 const old=window.renderOffersFit;window.renderOffersFit=function(r){if(old)old(r);addCard(r)};
})();
</script>
'''
if 'id="orfab-recommendation-card-script"' not in s:
    s=s.replace('</body>',js+'\n</body>',1)
p.write_text(s,encoding='utf-8')
